#!/usr/bin/env python3# -*- coding: utf-8 -*-"""Created on Mon Jun 10 14:18:38 2024@author: homai"""import itertoolsimport argparsefrom sklearn.metrics import roc_curve, roc_auc_score, confusion_matrix, auc, f1_score, accuracy_scorefrom scipy.stats import sem, t, iqrimport matplotlib.pyplot as pltfrom sklearn import metricsimport pandas as pdimport numpy as npimport torchimport osimport sysimport matplotlib.patches as mpatchesfrom scipy.stats import dirichlet, multinomial, betafrom scipy.special import gammaln, psiimport warningswarnings.filterwarnings("ignore")from sklearn.model_selection import train_test_splitfrom sklearn.preprocessing import MinMaxScalerscaler = MinMaxScaler()def calculate_roc_points(y_true, y_prob, thresholds):    tpr_list = []    fpr_list = []    for threshold in thresholds:        # Calculate predictions based on threshold        y_pred = (y_prob >= threshold).astype(int)        # Calculate true positives, false positives, true negatives, false negatives        tp = np.sum((y_pred == 1) & (y_true == 1))        fp = np.sum((y_pred == 1) & (y_true == 0))        tn = np.sum((y_pred == 0) & (y_true == 0))        fn = np.sum((y_pred == 0) & (y_true == 1))                # # Calculate TPR and FPR        tpr = tp / (tp + fn)        fpr = fp / (fp + tn)                # # Append TPR and FPR to lists        tpr_list.append(tpr)        fpr_list.append(fpr)    roc_auc = auc(fpr_list, tpr_list)    return roc_auc, fpr_list, tpr_list    def find_bad_ROC_chunk(res, prob_col, thresholds):    thresholds = thresholds[np.isfinite(thresholds)]  # Filter out non-finite thresholds    print(thresholds)        acc_best = 0    acc = 0        step_sizes = np.arange(int(len(thresholds)/2 - len(thresholds)/6)) # [6]  # List of step sizes to try        print(f'\n Tuning cut-offs to find ROC mid-chunk on VALIDATION set using multiple step sizes!\n')        # Loop over different step sizes    for step_sz in step_sizes:        print(f"Trying step size: {step_sz}")        for i in range(0, len(thresholds) - step_sz, step_sz):            midchunk_df = pd.DataFrame()                        # Filtering based on thresholds            midchunk_df = res[~res[prob_col].between(thresholds[i + step_sz], thresholds[i])]                        if len(midchunk_df) > 0:                # Assign 0 or 1 based on threshold comparison                midchunk_df[prob_col] = np.where(midchunk_df[prob_col] <= thresholds[i + step_sz],                                                 0,                                                 np.where(midchunk_df[prob_col] >= thresholds[i], 1, midchunk_df[prob_col]))                # Calculate accuracy                acc = np.mean(midchunk_df[prob_col] == midchunk_df['gt']) * 100                perc_data = (len(midchunk_df) / len(res)) * 100                # Check if this step size and thresholds give better accuracy                if acc > acc_best:                    a_up = i                    b_lo = i + step_sz                    # print(f'{prob_col}: [{a_up}, {b_lo}] thresholds= [{thresholds[i + step_sz]:.5f}, {thresholds[i]:.5f}], acc= {acc:.2f}, %Data= {perc_data:.3f}\n')                    low_thresh = thresholds[b_lo]                    upp_thresh = thresholds[a_up]                    acc_best = acc        print('=' * 70)    return a_up, b_lo, low_thresh, upp_thresh, acc_best, perc_datadef find_intervals(arr, window_size):    # Ensure window_size is a valid number    if window_size < 1 or window_size >= len(arr):        raise ValueError("Window size must be between 1 and the length of the array - 1.")        intervals = []    indices   = []        # Loop through the array and find intervals of length `window_size`    for i in range(len(arr) - window_size):        a = arr[i]        b = arr[i + window_size]        intervals.append(((i + window_size, b), (i, a)))  # Include indices with values        indices.append([i, i + window_size])    # print(indices)    return intervalsdef find_intervals2(arr):    intervals = []    indices   = []        # Loop through the array and find intervals of length `window_size`    for i in range(len(arr)):        for j in range(i + 1, len(arr)):            a = arr[i]            b = arr[j]            intervals.append(((j, b), (i, a)))  # Include indices with values            indices.append([i, j])    # print(indices)    return intervalsdef bad_ROC_chunks_remover(res, prob_col, thresh):    acc_best    = 0    acc         = 0    row         = -1    val_res     = pd.DataFrame()     # print(f'\n Tunning cut-offs to find ROC bad chunk on VALIDATION set!\n')            # if len(thresh) > 15:    #     window_sizes = np.arange(1,int(len(thresh)/2 - len(thresh)/6))    # else:    #     window_sizes = np.arange(1,len(thresh)-1)        window_sizes = np.arange(1,len(thresh)-1)    # print(window_sizes)    for window_sz in window_sizes:        # print(f'======> Trying window size= {window_sz}')                intervals = find_intervals(thresh, window_sz)    # intervals = find_intervals2(thresh)        for (idx1, val1), (idx2, val2) in intervals:            row += 1            chunk_df = pd.DataFrame()                        chunk_df = res[~res[prob_col].between(val1, val2)]                   if len(chunk_df) > 0:                     chunk_df[prob_col] = np.where(chunk_df[prob_col] <= val1,                                       0,                                       np.where(chunk_df[prob_col] >= val2, 1, chunk_df[prob_col]))                                    acc = np.mean(chunk_df[prob_col] == chunk_df['gt'])*100                perc_data = (len(chunk_df)/len(res))*100                            val_res.loc[row, 'b_lo']    = idx2                val_res.loc[row, 'a_up']    = idx1                val_res.loc[row, 'low_thresh']    = val1                val_res.loc[row, 'upp_thresh']    = val2                val_res.loc[row, 'val_accs']      = acc                val_res.loc[row, 'val_perc_data'] = perc_data                                if acc > acc_best:                    a_up = idx1                    b_lo = idx2                    # print(f'{prob_col}: [{b_lo}, {a_up}] treasholds= [{val1:.4f}, {val2:.4f}], acc= {acc:.2f}, %Data= {perc_data:.3f}') #window_sz= {window_sz},                     low_thresh  = val1                    upp_thresh  = val2                    acc_best    = acc    print('='*70)    val_res = val_res.reset_index()    return b_lo, a_up, low_thresh, upp_thresh, acc_best, val_resdef alg0(res, dm): # Probabilities    avg_prob_class1 = (df[f'{dm}_base_prob1'] + df[f'{dm}_meta_prob1']) / 2    scores          = avg_prob_class1    return scores # scaler.fit_transform(np.array(scores).reshape(-1, 1)).flatten()def alg1(res, model, dm): # Probabilities    scores = res[f'{dm}_{model}_prob1']    return scores # scaler.fit_transform(np.array(scores).reshape(-1, 1)).flatten()def alg2(res, model, dm): # Uncertainties    if model == 'meta':        scores = res[f'{dm}_{model}_diffent']    elif model == 'base':        scores = res[f'{dm}_{model}_entropy']    return scores # scaler.fit_transform(np.array(scores).reshape(-1, 1)).flatten()    def alg3(res, dm): # CDF(0.5)    scores = []    for irow in range(len(res)):        alfa  = [res.loc[irow, f'{dm}_alfa0'], res.loc[irow, f'{dm}_alfa1']]         cdf = beta.cdf(0.5,  alfa[0], alfa[1])        scores.append(cdf)    return scores # scaler.fit_transform(np.array(scores).reshape(-1, 1)).flatten()# Binary Classificationdef binary_roc_curve(y_true, y_pred):    fpr, tpr, thresholds = roc_curve(y_true, y_pred)    roc_auc = auc(fpr, tpr)    return roc_auc, fpr, tpr, thresholdsdef plot_roc_curve(roc_auc, fpr, tpr, colr, transp, fnam, ii, ax):    ax.plot(fpr, tpr, color=colr, alpha= 0.8)    # ax.scatter(fpr, tpr, color=colr, alpha= 0.7, s=30)    ax.plot([0, 1], [0, 1], color='navy', linestyle='--', linewidth=3)    ax.set_xlim([0.0, 1.0])    ax.set_ylim([0.0, 1.05])    ax.set_xlabel('False Positive Rate', fontsize=16)    ax.set_ylabel('True Positive Rate', fontsize=16)    ax.set_title(f'{fnam} dataset', fontsize=13, fontweight='bold')    return f'$AUC_{ii}$= {roc_auc:.2f}'    def get_auc_per_alg(val_data, nn, fname, ax):    auc_valus =[]; handls = []    for i in range(1, nn):        auc_val, fpr_list, tpr_list, _ = binary_roc_curve(val_data['gt'], val_data[f'w{i}_scores'])        labl = plot_roc_curve(auc_val, fpr_list, tpr_list, 'gray', 0.5, fname, i, ax)        auc_valus.append([i, auc_val])        handls.append(mpatches.Patch(color= 'gray', label= labl))        del auc_val, fpr_list, tpr_list, labl        print(f'Got ROC for {i} scores.')    return auc_valus, handlsdef get_best_auc_index(auc_valus):    max1 = float('-inf')    max2 = float('-inf')    index1 = -1    index2 = -1        for idx, (index, value) in enumerate(auc_valus):        if value > max1:            max2 = max1            index2 = index1            max1 = value            index1 = index        elif value > max2:            max2 = value            index2 = index    return index1, index2def get_best_auc(i_star, auc_valus, val_data, fname, handls, axs):    # i_star, max_auc = max(auc_valus, key=lambda x: x[1])    best_auc, best_fpr, best_tpr, best_thresh = binary_roc_curve(val_data['gt'], val_data[f'w{i_star}_scores'])        labl = plot_roc_curve(best_auc, best_fpr, best_tpr, 'blue', 0.8, fname, i_star, axs)        handls[i_star-1] = mpatches.Patch(color= 'blue', label= 'Best '+labl)    ## handls.append(mpatches.Patch(color= 'blue', label= 'Best '+labl))    return best_auc, best_fpr, best_tpr, best_thresh, handlsdef cal_confusion_metrix(df, pred_col, label_col, score_col, threshold=0.5):    # Convert scores to binary predictions    df[pred_col] = (df[score_col] >= threshold).astype(int)    # Calculate TP, TN, FP, FN    tp = ((df[label_col] == 1) & (df[pred_col] == 1)).sum()    tn = ((df[label_col] == 0) & (df[pred_col] == 0)).sum()    fp = ((df[label_col] == 0) & (df[pred_col] == 1)).sum()    fn = ((df[label_col] == 1) & (df[pred_col] == 0)).sum()    f1score = f1_score(df[label_col], df[pred_col])    return tp, tn, fp, fn, f1score*100def calc_eval_metrics(tp, tn, fp, fn):    sensitivity = tp / (tp + fn) # Recall    specificity = tn / (tn + tp)    precision = tn / (tn + fp) if (tn + fp) != 0 else 0    return sensitivity*100, specificity*100, precision*100def get_unique_vals(values):    threshold = 1.0    grouped_values = []    group_leader = values[0]        for i, value in enumerate(values):        if i == 0:            grouped_values.append(group_leader)        elif abs(value - group_leader) >= threshold:            grouped_values.append(value)            group_leader = value        grouped_values = np.array(grouped_values)    return grouped_valuesdef pareto_frontier(df):    xpareto, ypareto = [], []    xi_uniq = np.unique(df['perc_censored'])    # xi_uniq = xi_uniq[xi_uniq>10]    xi_uniq_grouped = get_unique_vals(xi_uniq)    # print(xi_uniq_grouped)    # for xi in xi_uniq:    for xi in xi_uniq_grouped:          xpareto.append(xi)        ypareto.append(df[df['perc_censored']<=xi]['val_accs'].max())    return xpareto, yparetodef plot_validation_acc_percData(val_tuning_df, savDir):    fig, ax = plt.subplots(1,1, figsize=(6,5))    val_tuning_df['perc_censored'] = 100 - val_tuning_df['val_perc_data']    ax.scatter(val_tuning_df['perc_censored'], val_tuning_df['val_accs'], c = 'gray', edgecolors='k', alpha=0.4, s=60)        pareto_x, pareto_y = pareto_frontier(val_tuning_df)    ax.scatter(pareto_x, pareto_y, c = 'purple', edgecolors='k', s=60, alpha=1)    plt.axhline(y=95, color='green', linestyle='--', linewidth=1)    ax.set_xlabel('(%) Censored validation data', fontsize=15)    ax.set_ylabel('(%) Validation accuracy', fontsize=15)        ax.tick_params(axis='x', labelsize=15, size=15)  # Change x-tick label size    ax.tick_params(axis='y', labelsize=15, size=15)  # Change y-tick label size        plt.tight_layout(); #plt.title('Optimizing best self-censorship thresholds based \non accuracy-%data trade-offs')    ax.grid(True, which='both', alpha=0.2); ax.set_xlim([0,100]); ax.set_ylim([0,104])        handles.append(mpatches.Patch(color= 'purple',  label= f'Efficient frontier'));     handles.append(mpatches.Patch(color= 'gray',  label= f'Suboptimal thresholds'));     handles.append(mpatches.Patch(color= 'green',  label= f'Clinically acceptable'));     axs.legend(handles=handles, bbox_to_anchor=(0.5, -0.16), loc='upper center', fontsize=16, ncol=2)        plt.savefig(savDir, dpi=350, bbox_inches='tight') #, pad_inches=0.2    def selfcens_test_acc_percdt(test_data, thrsh_lo, thrsh_up, methd, istar):    test_df_filter = test_data[~test_data[f'w{istar}_scores'].between(thrsh_lo, thrsh_up)]    test_df_filter['new_preds'] = np.where(test_df_filter[f'w{istar}_scores'] <= thrsh_lo, 0,                                              np.where(test_df_filter[f'w{istar}_scores'] >= thrsh_up, 1, test_df_filter[f'w{istar}_scores']))        test_acc = np.mean(test_df_filter['new_preds'] == test_df_filter['gt'])*100    test_auc,_,_,_ = binary_roc_curve(test_df_filter['gt'], test_df_filter[f'w{istar}_scores'])    tp_test, tn_test, fp_test, fn_test, f1_test = cal_confusion_metrix(test_df_filter, 'predicted', 'gt', f'w{istar}_scores', threshold=0.5)    sen_test, spe_test, ppv_test = calc_eval_metrics(tp_test, tn_test, fp_test, fn_test)    perc_data_test = (len(test_df_filter)/len(test_data))*100    print(f'========**>> Window size: [{thrsh_lo:.2f}, {thrsh_up:.2f}], w{istar}_scores => ')    print(f'===============> {methd} model + self-censorship:')    print(f'%Data= {perc_data_test:.2f}, \nTest acc= {test_acc:.2f}, \nSEN= {sen_test:.2f}, \nSPE= {spe_test:.2f}, \nPPV= {ppv_test:.2f}, \nAUC= {test_auc*100:.2f}, \nf1 score= {f1_test:.2f}')    return test_df_filterdef get_baseline_perfromance(df, dt, method):    test_acc = np.mean(df[f'{dt}_{method}_preds'] == df['gt'])*100    test_auc,_,_,_ = binary_roc_curve(df['gt'], df[f'{dt}_{method}_prob1'])    tp_test, tn_test, fp_test, fn_test, f1_test = cal_confusion_metrix(df, 'predicted', 'gt', f'{dt}_{method}_prob1', threshold=0.5)    sen_test, spe_test, ppv_test = calc_eval_metrics(tp_test, tn_test, fp_test, fn_test)    perc_data_test = (len(df)/len(df))*100    print(f'========**>> {method} baseline model on {dt} data: => ')    print(f'%Data= {perc_data_test:.2f}, \nTest acc= {test_acc:.2f}, \nSEN= {sen_test:.2f}, \nSPE= {spe_test:.2f}, \nPPV= {ppv_test:.2f}, \nAUC= {test_auc*100:.2f}, \nf1 score= {f1_test:.2f}')    sen_at_spec(df['gt'], df[f'{dt}_{method}_prob1'], [0.99, 0.975, 0.95, 0.90])def sen_at_spec(true_y, scores_y, desired_spec_levels): # sensitivity at a specific specificity threashold    fpr, tpr, thresholds = roc_curve(true_y, scores_y)    specificity = 1 - fpr    sensitivity_at_spec = {}    for spec in desired_spec_levels:        idx = np.where(specificity >= spec)[0]        if len(idx) == 0:            sensitivity_at_spec[spec] = None  # not reachable        else:            best_idx = idx[-1]  # get the last one before dropping below threshold            sensitivity_at_spec[spec] = tpr[best_idx]            print(f'Sensitivity @ {spec} specificity= {sensitivity_at_spec[spec]*100:.3f}')    print('='*60);     def get_baseline_perfromance_ensemble(datadf, dt, method):    # Accuracy    test_acc = accuracy_score(datadf['gt'], datadf[f'{dt}_ensemble_preds'])    test_auc,_,_,_ = binary_roc_curve(datadf['gt'], datadf[f'{dt}_ensemble_prob1'])    tp_test, tn_test, fp_test, fn_test, f1_test = cal_confusion_metrix(datadf, 'predicted', 'gt', f'{dt}_ensemble_prob1', threshold=0.5)    sen_test, spe_test, ppv_test = calc_eval_metrics(tp_test, tn_test, fp_test, fn_test)        perc_data_test = (len(datadf)/len(datadf))*100    print(f'========**>> {method} baseline model on {dt} data: => ')    print(f'%Data= {perc_data_test:.2f}, \nTest acc= {test_acc:.3f}, \nSEN= {sen_test:.2f}, \nSPE= {spe_test:.2f}, \nPPV= {ppv_test:.2f}, \nAUC= {test_auc*100:.2f}, \nf1 score= {f1_test:.2f}')    sen_at_spec(datadf['gt'], datadf[f'{dt}_ensemble_prob1'], [0.99, 0.975, 0.95, 0.90])    return def add_ensemble_scores(datadf, dt):    datadf[f'{dt}_base_prob0'] = 1- datadf[f'{dt}_base_prob1']    datadf[f'{dt}_meta_prob0'] = 1- datadf[f'{dt}_meta_prob1']        # Average probabilities    avg_prob_class0 = (datadf[f'{dt}_base_prob0'] + datadf[f'{dt}_base_prob0']) / 2    avg_prob_class1 = (datadf[f'{dt}_base_prob1'] + datadf[f'{dt}_meta_prob1']) / 2        # Ensemble prediction: pick class with higher average probability    ensemble_preds = np.where(avg_prob_class1 > avg_prob_class0, 1, 0)    datadf[f'{dt}_ensemble_prob1'] = avg_prob_class1    datadf[f'{dt}_ensemble_preds'] = ensemble_preds    return datadfif __name__=="__main__":     parser = argparse.ArgumentParser(description='Self-censorship approach')    parser.add_argument('--path', default='../../results/', type=str, help='the directory path to results')    parser.add_argument('--score_func', default='all', type=str, choices=['SDL', 'Dir', 'all'], help='SDL= standard DL, Dir= Dirichlet, all = SDL + Dir+ensemble')    parser.add_argument('--dt', default='ood', type=str, choices=['ind', 'ood'], help='ind= in-distribution, ood= out-of-distribution')    parser.add_argument('--fname', default='REFUGE', type=str, help='name of dataset result')    args = parser.parse_args()        plot =False    fname= args.fname    fig, axs = plt.subplots(1,1, figsize=(7, 7))    # ================ Load actual results    df           = pd.read_csv(os.path.join(args.path, f'{fname}_probs.csv'))    if args.dt == 'ind':        fname = 'UIC'        df = df.loc[:, df.columns.str.startswith('ind')]        df = df.dropna()    saving_name = f'{fname}_ROC_to_censor'    # ================ Create a new df with gt and different scoring functions    df_new       = pd.DataFrame()    df_new['gt'] = df[f'{args.dt}_labels']         if args.fname == 'REFUGE' and args.dt == 'ood':        rand_state = 43 #rim:20, lag:20, origa:20, ref:43 # other good seeds: 44, 99, 777,     elif args.dt == 'ind':        rand_state = 30 # 11, 15, 27    else:        rand_state = 20 #rim:20, lag:20, origa:20, ref:43 # other good seeds: 44, 99, 777,         if args.score_func == 'all':        df_new['w1_scores']  = alg1(df, 'base', args.dt) # p softmax        df_new['w2_scores']  = alg1(df, 'meta', args.dt) # p dirichlet        n_cols = 3    elif args.score_func == 'SDL':        df_new['w1_scores']  = alg1(df, 'base', args.dt) # p softmax        n_cols = 2    elif args.score_func == 'Dir':        df_new['w1_scores']  = alg1(df, 'meta', args.dt) # p dirichlet        n_cols = 2    elif args.score_func == 'ensemble':        df_new['w1_scores']  = alg0(df, args.dt) # p dirichlet        n_cols = 2            df_new[f'{args.dt}_base_preds'] = df[f'{args.dt}_base_preds']     df_new[f'{args.dt}_meta_preds'] = df[f'{args.dt}_meta_preds']     df_new[f'{args.dt}_base_prob1'] = df[f'{args.dt}_base_prob1']    df_new[f'{args.dt}_meta_prob1'] = df[f'{args.dt}_meta_prob1']                 # ================ Baseline performances for Ensemble    # df_new = add_ensemble_scores(df_new, args.dt)        # ================ Split df into train and validation sets    test_df, val_df = train_test_split(df_new, test_size=0.1, random_state=rand_state)    val_df  = val_df.reset_index(drop=True)    test_df = test_df.reset_index(drop=True)        # ================ Baseline performances    get_baseline_perfromance(test_df, args.dt, 'base')    get_baseline_perfromance(test_df, args.dt, 'meta')        # get_baseline_perfromance_ensemble(test_df, args.dt, 'ensemble')        # ================ Calculate AUC per scoring function and plot AUROCs on validation    auc_vals, handles = get_auc_per_alg(val_df, n_cols, fname, axs)            # ================ Get best AUC and istar on validation    istar1, istar2 = get_best_auc_index(auc_vals)    if istar1==1:        method ='base'    elif istar1==2:        method = 'meta'    # elif istar1==3:    #     method = 'ensemble'        # ================ Get the best AUC    auc_best, fpr_best, tpr_best, thresh_best, handles = get_best_auc(istar1, auc_vals, val_df, fname, handles, axs)        tp_best, tn_best, fp_best, fn_best, f1_best = cal_confusion_metrix(test_df, 'predicted', 'gt', f'w{istar1}_scores', threshold=0.5)    # ================ Get optimal mid-chunk of ROC on validation    thresh_best = np.arange(thresh_best[1], thresh_best[-1], -0.005)         aa, bb, lo_thresh, up_thresh, best_val_acc, val_tuning_res = bad_ROC_chunks_remover(val_df, f'w{istar1}_scores', thresh_best)    # ================ Get optimal mid-chunk of ROC on validation    chunk_thr_censored = list(thresh_best[:aa]) + list(thresh_best[bb:])        test_df_filtered = test_df[~test_df[f'w{istar1}_scores'].between(lo_thresh, up_thresh)]    test_df_filtered['new_preds'] = np.where(test_df_filtered[f'w{istar1}_scores'] <= lo_thresh, 0,                                              np.where(test_df_filtered[f'w{istar1}_scores'] >= up_thresh, 1, test_df_filtered[f'w{istar1}_scores']))        ### ====> Index of best results per validation set: UIC=4, RIM=44, ORIG=62, REF=13, LAG=4872    ### ====>  ### ====>  ### ====>  ### ====>  ### ====>  ### ====>  ### ====>     #===================== THIS PART CAN BE TUNED, COMMENTE, OR CHANGED BASED ON THE USER'S PREFERENCE IN BALANCING ACCURACY VS. %DATA    if fname == 'UIC':        test_df_filtered= selfcens_test_acc_percdt(test_df, val_tuning_res.loc[4,'low_thresh'], val_tuning_res.loc[4,'upp_thresh'], args.score_func, istar1)    elif fname == 'RIMEONE-DL':        test_df_filtered= selfcens_test_acc_percdt(test_df, val_tuning_res.loc[44,'low_thresh'], val_tuning_res.loc[44,'upp_thresh'], args.score_func, istar1)        elif fname == 'ORIGA':        test_df_filtered= selfcens_test_acc_percdt(test_df, val_tuning_res.loc[62,'low_thresh'], val_tuning_res.loc[62,'upp_thresh'], args.score_func, istar1)        elif fname == 'REFUGE':        test_df_filtered= selfcens_test_acc_percdt(test_df, val_tuning_res.loc[13,'low_thresh'], val_tuning_res.loc[13,'upp_thresh'], args.score_func, istar1)        elif fname == 'LAG':        test_df_filtered= selfcens_test_acc_percdt(test_df, val_tuning_res.loc[4872,'low_thresh'], val_tuning_res.loc[4872,'upp_thresh'], args.score_func, istar1)            ### ====> ### ====>  ### ====>  ### ====>  ### ====>  ### ====>  ### ====>          test_acc = np.mean(test_df_filtered['new_preds'] == test_df_filtered['gt'])*100    test_auc_selfcns,_,_,_ = binary_roc_curve(test_df_filtered['gt'], test_df_filtered[f'{args.dt}_{method}_prob1'])    tp_test, tn_test, fp_test, fn_test, f1_test = cal_confusion_metrix(test_df_filtered, 'predicted', 'gt', f'w{istar1}_scores', threshold=0.5)        sen_test, spe_test, ppv_test = calc_eval_metrics(tp_test, tn_test, fp_test, fn_test)        auc_test, fpr_test, tpr_test = calculate_roc_points(test_df_filtered['gt'], test_df_filtered[f'w{istar1}_scores'], chunk_thr_censored)    perc_data_test = (len(test_df_filtered)/len(test_df))*100    print(f'---> Best HP on validation: w{istar1}_scores within [{bb}, {aa}]= [{lo_thresh:.4f}, {up_thresh:.4f}]')    print(f'===============> {args.score_func} model + self-censorship:')    print(f'%Data= {perc_data_test:.2f}, \nTest acc= {test_acc:.2f}, \nSEN= {sen_test:.2f}, \nSPE= {spe_test:.2f}, \nPPV= {ppv_test:.2f}, \nAUC= {test_auc_selfcns*100:.2f}, \nf1 score= {f1_test:.2f}')    sen_at_spec(test_df_filtered['gt'], test_df_filtered[f'w{istar1}_scores'], [0.99, 0.975, 0.95, 0.90])    ## ================     if plot:        axs.plot(fpr_test, tpr_test, color = 'green', linewidth= 3)         axs.scatter(fpr_best[aa], tpr_best[aa], c = 'red', marker = 'X', s=140)         axs.scatter(fpr_best[bb], tpr_best[bb], c = 'red', marker = 'X', s=140)              axs.plot(fpr_best[aa:bb+1], tpr_best[aa:bb+1], c = 'lime', linewidth=3)                    axs.tick_params(axis='x', labelsize=16)  # Change x-tick label size        axs.tick_params(axis='y', labelsize=16)  # Change y-tick label size                axs.tick_params(axis='x', size=16)  # Change x-tick size        axs.tick_params(axis='y', size=16)  # Change y-tick size                handles.append(mpatches.Patch(color= 'lime',  label= f'Removed'))        handles.append(mpatches.Patch(color= 'green', label= f'Self-censor AUC= {auc_test:.2f}'))            ## ================ Save figure        plt.tight_layout();         axs.legend(handles=handles, bbox_to_anchor=(0.5, -0.16), loc='upper center', fontsize=16, ncol=3)        # plt.savefig(args.path + f'{saving_name}.png', dpi=300, bbox_inches='tight') #, pad_inches=0.2                    #### =============== test AUROC        fig, ax2 = plt.subplots(1,1, figsize=(7, 7))        roc_auc, fpr, tpr, thresholds = binary_roc_curve(test_df_filtered['gt'], test_df_filtered[f'w{istar1}_scores'])        ax2.tick_params(axis='x', labelsize=16, size=16)  # Change x-tick label size        ax2.tick_params(axis='y', labelsize=16, size=16)  # Change y-tick label size                leg = plot_roc_curve(roc_auc, fpr, tpr, 'purple', 0.8, fname, '{test}', ax2)        ax2.legend([leg], loc='lower right', fontsize=20)        # plt.savefig(args.path + f'{saving_name}_test.png', dpi=300, bbox_inches='tight') #, pad_inches=0.2            if args.score_func == 'all':        #### ================================ softmax results exclusively on the uncensored data        test_acc_sfx = np.mean(test_df_filtered[f'{args.dt}_base_preds'] == test_df_filtered['gt'])*100        test_auc_sfx,_,_,_ = binary_roc_curve(test_df_filtered['gt'], test_df_filtered['w1_scores'])        tp_sfx, tn_sfx, fp_sfx, fn_sfx, f1_sfx = cal_confusion_metrix(test_df_filtered, 'predicted', 'gt', 'w1_scores', threshold=0.5)        sen_sfx, spe_sfx, ppv_sfx = calc_eval_metrics(tp_sfx, tn_sfx, fp_sfx, fn_sfx)        print(f'===============> Softmax + Self-Censorship on the same retained data by self-censorship (Table 4):')        print(f'%Data= {perc_data_test:.2f}, \nTest acc= {test_acc_sfx:.2f}, \nSEN= {sen_sfx:.2f}, \nSPE= {spe_sfx:.2f}, \nPPV= {ppv_sfx:.2f}, \nAUC={test_auc_sfx*100:.2f}, \nf1 score= {f1_sfx:.2f}')        print(f'%Data= {perc_data_test:.2f}, \nTest acc= {test_acc_sfx:.2f}')        sen_at_spec(test_df_filtered['gt'], test_df_filtered['w1_scores'], [0.99, 0.975, 0.95, 0.90])        #### ================================ dirichlet results exclusively on the uncensored data            test_acc_dir = np.mean(test_df_filtered[f'{args.dt}_meta_preds'] == test_df_filtered['gt'])*100        test_auc_dir,_,_,_ = binary_roc_curve(test_df_filtered['gt'], test_df_filtered['w2_scores'])        tp_dir, tn_dir, fp_dir, fn_dir, f1_dir = cal_confusion_metrix(test_df_filtered, 'predicted', 'gt', 'w2_scores', threshold=0.5)        sen_dir, spe_dir, ppv_dir = calc_eval_metrics(tp_dir, tn_dir, fp_dir, fn_dir)        print(f'===============> Dirichlet + Self-Censorship on the same retained data by self-censorship (Table 4):')        print(f'%Data= {perc_data_test:.2f}, \nTest accuracy= {test_acc_dir:.2f}, \nSEN= {sen_dir:.2f}, \nSPE= {spe_dir:.2f}, \nPPV= {ppv_dir:.2f}, \nAUC={test_auc_dir*100:.2f}, \nf1 score= {f1_dir:.2f}')        print(f'%Data= {perc_data_test:.2f}, \nTest accuracy= {test_acc_dir:.2f}')        sen_at_spec(test_df_filtered['gt'], test_df_filtered['w2_scores'], [0.99, 0.975, 0.95, 0.90])        #### ================================ ensembe results exclusively on the uncensored data            test_acc_ensmbl = np.mean(test_df_filtered[f'{args.dt}_ensemble_preds'] == test_df_filtered['gt'])*100        print(f'===============> Ensemble + Self-Censorship on the same retained data by self-censorship (Table 4):')        print(f'%Data= {perc_data_test:.2f}, \nTest acc= {test_acc_ensmbl:.2f}')        sen_at_spec(test_df_filtered['gt'], test_df_filtered['w3_scores'], [0.99, 0.975, 0.95, 0.90])    plot_validation_acc_percData(val_tuning_res, os.path.join(args.path,f'{args.fname}_val_selfcensor2.png'))               